[TFMDescription("Expression to find the default issue location of a certain item. Takes ItemId, and InventLocationid as Parameters")]
class TFMExpressionsDefaultIssueLocation extends TFMExpressions
{

}

Method.Source:
public str processExpressionValue(str _value, InventLocationid _inventLocationId = '')
{
    str ret;
    InventDim inventDimFinalWhs;
    inventDimFinalWhs.clear();
    inventDimFinalWhs.InventLocationId = _inventLocationId;
    inventDimFinalWhs = InventDim::findOrCreate(inventDimFinalWhs);
    ret = inventDimFinalWhs.inventDimId ? InventItemLocation::findFixedWarehouse(_value,inventDimFinalWhs.inventDimId).WMSLocationIdDefaultIssue : '';

    return ret;
}
